import torch.nn.functional as F


class Model(nn.Module):
    def __init__(self, input_channels, input_dims, transpose=False):
        super().__init__()
        if transpose:
            self.softmax_permute = nn.Softmax(dim=-2)  # permute dims for transpose operation
        else:
            self.softmax_permute = nn.Softmax(dim=-1)  # permute dims for normal softmax

    def forward(self, x):
        x = F.softmax(x, dim=self.softmax_permute.dim)
        x = torch.permute(x, (0, 2, 1, 3))  # permute dims here
        return x


